const programCard=(p,link,role,t,h,btn)=>`<article class="rule stack"><div class="row space wrap"><h3>${h(p.title)}</h3><span class="badge ${p.archived?'gold':'green'}">${t(p.archived?'coachingArchived':p.completedAt?'done':'coachingActive')}</span></div><ul class="coaching-exercises">${p.exercises.map(x=>`<li>${h(x)}</li>`).join('')}</ul>${p.notes?`<p class="post-text">${h(p.notes)}</p>`:''}${!p.archived&&link?`<div class="row wrap">${role==='coach'?btn(t('wellnessEdit'),'coachingProgramEdit',`data-id="${h(p.id)}" data-link="${h(link.id)}"`,'secondary')+btn(t('coachingArchive'),'coachingProgramArchive',`data-id="${h(p.id)}" data-link="${h(link.id)}"`,'secondary'):btn(t(p.completedAt?'coachingReopen':'coachingComplete'),'coachingProgramComplete',`data-id="${h(p.id)}" data-link="${h(link.id)}" data-completed="${!p.completedAt}"`,'secondary')}</div>`:''}</article>`;
export function coachingPanel({state,t,h,btn,candidates=[]}){
  const c=state.coaching;
  if(!c)return `<section class="card stack"><h2>${t('coachingManagement')}</h2><p>${t('coachingContext')}</p>${btn(t('identitySwitchLabel'),'nav','data-id="identity"','secondary')}</section>`;
  const role=c.role,connected=new Set(c.links.map(l=>l.otherId));
  return `<section class="card stack"><div class="row space wrap"><h2>${t(role==='coach'?'coachingTrainees':'coachingMyCoaches')}</h2><span class="badge gold">${t('wellnessLocal')}</span></div><p>${t('coachingConsent')}</p><p class="notice">${t('wellnessLocalNotice')}</p><form class="stack" data-form="coachingInvite"><label>${t(role==='coach'?'coachingSelectMember':'coachingSelectCoach')}<select name="target" required><option value="">${t('choosePeople')}</option>${candidates.filter(p=>p.id!==state.me.id&&!connected.has(p.id)&&(role==='coach'?p.role!=='admin':p.role==='coach'&&p.verified)).map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select></label><button class="primary" type="submit">${t('coachingInvite')}</button></form></section>${c.links.map(l=>`<section class="card stack"><div class="row space wrap"><h2>${h(l.otherName)}</h2><span class="badge ${l.status==='active'?'green':'gold'}">${t(l.status==='active'?'coachingActive':l.incoming?'coachingIncoming':'coachingPending')}</span></div>${l.status==='pending'?`<div class="row wrap">${l.incoming?btn(t('accept'),'coachingResponse',`data-id="${h(l.id)}" data-accept="true"`,'primary')+btn(t('decline'),'coachingResponse',`data-id="${h(l.id)}" data-accept="false"`,'secondary'):btn(t('coachingCancel'),'coachingEnd',`data-id="${h(l.id)}"`,'secondary')}</div>`:`<div class="row wrap">${role==='coach'?btn(t('coachingAddProgram'),'coachingProgramNew',`data-id="${h(l.id)}"`,'primary'):btn(t(l.shareWorkout?'coachingStopSharing':'coachingShare'),'coachingShare',`data-id="${h(l.id)}" data-enabled="${!l.shareWorkout}" ${!c.canShareWorkout&&!l.shareWorkout?'disabled':''}`,'secondary')}${btn(t('coachingEnd'),'coachingEnd',`data-id="${h(l.id)}"`,'danger')}</div><p class="muted">${t(l.shareWorkout?'coachingSharingOn':'coachingSharingOff')}</p>${role==='member'&&!c.canShareWorkout?`<p class="notice">${t('coachingEnableLogs')}</p>`:''}<h3>${t('coachPrograms')}</h3>${l.programs.map(p=>programCard(p,l,role,t,h,btn)).join('')||`<p class="empty">${t('noItems')}</p>`}${role==='coach'&&l.progress?`<div class="rule stack"><h3>${t('traineeProgress')}</h3><p>${t('coachingWorkoutCount')}: <b>${h(l.progress.count)}</b></p><small>${t('coachingRecent')}</small>${l.progress.recent.map(r=>`<div class="rule"><b>${h(r.recordExercise)}</b><br><small>${h(r.recordDate)} · ${h(r.recordSets)} × ${h(r.recordReps)} · ${h(r.recordWeight)} kg</small></div>`).join('')}</div>`:''}`}</section>`).join('')||`<p class="empty">${t('noItems')}</p>`}${c.pastPrograms.length?`<section class="card stack"><h2>${t('coachingPastPrograms')}</h2>${c.pastPrograms.map(p=>programCard(p,null,'member',t,h,btn)).join('')}</section>`:''}`;
}
export function assignedPrograms({state,t,h,btn}){
  if(state.coaching?.role!=='member')return '';
  const active=state.coaching.links.filter(l=>l.status==='active');
  return `<section class="card stack"><h2>${t('coachingAssignedPrograms')}</h2>${active.flatMap(l=>l.programs).filter(p=>!p.archived).map(p=>`<p class="rule"><b>${h(p.title)}</b> · ${t(p.completedAt?'done':'coachingActive')}</p>`).join('')||`<small>${t('noItems')}</small>`}${btn(t('coachingManagement'),'nav','data-id="coaches"','secondary')}</section>`;
}
export function coachingProgramForm(p,t,h){
  return `<label>${t('recordTitle')}<input name="title" required maxlength="80" value="${h(p?.title||'')}"></label><label>${t('recordExercises')}<small>${t('recordExercisesHint')}</small><textarea name="exercises" required maxlength="2420">${h(p?.exercises.join('\n')||'')}</textarea></label><label>${t('coachingNotes')}<textarea name="notes" maxlength="500">${h(p?.notes||'')}</textarea></label>`;
}
